```sql
CREATE TABLE orders (
  id          INT PRIMARY KEY,
  customer_id INT NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id)
    ON DELETE CASCADE      -- deleting a customer deletes their orders
    ON UPDATE CASCADE      -- changing customers.id updates orders too
);

-- rejected: no customer 999 exists (referential integrity)
INSERT INTO orders (id, customer_id) VALUES (1, 999);

-- with CASCADE, this also removes that customer's orders:
DELETE FROM customers WHERE id = 5;
```

```sql
CREATE TABLE users (id INT, status VARCHAR(10) DEFAULT 'ACTIVE');

INSERT INTO users (id, status) VALUES (1, NULL);
-- stores NULL, NOT 'ACTIVE' -> default is bypassed by explicit NULL
```
